-- Kanarau Migration V17: Expand N2 and N1 Full 35-Day Curriculum Decks
-- Provides 5 full weeks of structured daily study decks for N2 and N1 (1,050 words each)

-- 1. Insert new N2 Decks (Day 13 - 35)

UPDATE decks SET kotoba_count = 30 WHERE id >= 1 AND id <= 12;

-- 2. Insert new N1 Decks (Day 4 - 35)

UPDATE decks SET kotoba_count = 30 WHERE id >= 101 AND id <= 103;

-- 3. Re-map clean 30 words per deck for Day 1..35
DELETE FROM deck_kotoba WHERE (deck_id >= 1 AND deck_id <= 12) OR (deck_id >= 101 AND deck_id <= 103);






-- Reset sequence beyond inserted IDs
SELECT setval(pg_get_serial_sequence('deck_kotoba', 'id'), GREATEST(3201, COALESCE((SELECT MAX(id) FROM deck_kotoba), 0)));
SELECT setval(pg_get_serial_sequence('decks', 'id'), GREATEST(1000, COALESCE((SELECT MAX(id) FROM decks), 0)));
